  ],
  "accents": []
};

export const meta = {
  "slug": "lucide-tag",
  "family": "lucide",
  "name": "tag",
  "category": "Commerce",
  "motion": "coin",
  "component": "createLucideTagIcon"
};

export function createLucideTagIcon(root, options = {}) {
  let current = { ...options };
  const render = () => {
    root.innerHTML = renderSetIcon(definition, current);
  };
  render();
  const controller = bindSetIcon(root, definition, () => current);
  return {
    play: controller.play,
    reset: controller.reset,
    destroy: controller.destroy,
    update(next = {}) {
      current = { ...current, ...next };
      render();
    },
    get observed() {
      return controller.observed;
    },
  };
}
